def bubble_trace(a):
    arr=a[:]
    n=len(arr)
    for i in range(n-1):
        print("Pass",i+1,"start",arr)
        swapped=False
        for j in range(n-1-i):
            print("  Step",j+1,"compare indices",j,"and",j+1,"values",arr[j],arr[j+1],end="")
            if arr[j]>arr[j+1]:
                arr[j],arr[j+1]=arr[j+1],arr[j]
                swapped=True
                print(" -> swapped ->",arr)
            else:
                print(" -> no swap ->",arr)
        if not swapped:
            print("  No swaps in this pass, break.")
            break
    print("final",arr)

bubble_trace([5,3,1,4,2])
